function RecipientForm({ onBack, onCancel, onSubmit }) {
  const [method, setMethod] = useState("email");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [note, setNote] = useState("");
  const [errors, setErrors] = useState({});

  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const phoneRe = /^\+?[0-9()\-\s]{7,15}$/;

  const validate = () => {
    const e = {};
    if (firstName.trim().length < 2) e.firstName = "First name must be at least 2 characters.";
    if (lastName.trim().length < 2) e.lastName = "Last name must be at least 2 characters.";
    if (method === "email") {
      if (!emailRe.test(email.trim())) e.email = "Enter a valid email address.";
    } else {
      if (!phoneRe.test(phone.trim())) e.phone = "Enter a valid mobile number.";
    }
    if (note.length > 500) e.note = "Note must be 500 characters or fewer.";
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const submit = () => {
    if (!validate()) return;
    onSubmit({
      firstName: firstName.trim(),
      lastName: lastName.trim(),
      email: method === "email" ? email.trim() : "",
      phone: method === "phone" ? phone.trim() : "",
      note: note.trim(),
      method,
    });
  };

  return (
    <div className="min-h-full flex flex-col bg-white">
      <TopBar title="Recipient Details" onBack={onBack} onCancel={onCancel} tone="blue" />
      <div className="p-4 flex-1 overflow-y-auto">
        <div className="text-xs font-semibold tracking-wide text-gray-500 mb-3">RECIPIENT DETAILS</div>

        <Field label="First Name" error={errors.firstName}>
          <input value={firstName} onChange={(e) => setFirstName(e.target.value)} placeholder="First Name" className={inputCls(errors.firstName)} />
        </Field>

        <Field label="Last Name" error={errors.lastName}>
          <input value={lastName} onChange={(e) => setLastName(e.target.value)} placeholder="Last Name" className={inputCls(errors.lastName)} />
        </Field>

        {method === "email" ? (
          <Field label="Email" error={errors.email}>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Enter Email Address" className={inputCls(errors.email)} />
          </Field>
        ) : (
          <Field label="Mobile Number" error={errors.phone}>
            <input type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="Mobile Number" className={inputCls(errors.phone)} />
          </Field>
        )}

        <button onClick={() => setMethod(method === "email" ? "phone" : "email")} className="text-xs text-blue-600 font-medium mb-4">
          Use {method === "email" ? "Mobile Number" : "Email"} instead
        </button>

        <div className="mb-1 text-xs font-medium text-gray-500">Note</div>
        <textarea
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="Add an optional note"
          rows={3}
          className="w-full px-3 py-2 rounded border border-gray-300 text-sm resize-none focus:outline-none focus:border-blue-600 focus:ring-1 focus:ring-blue-600"
        />
        {errors.note && <div className="text-xs text-red-600 mt-1">{errors.note}</div>}
      </div>

      <div className="p-4 border-t border-gray-300 flex gap-3">
        <SecondaryButton onClick={onBack}>&lsaquo; Back</SecondaryButton>
        <PrimaryButton onClick={submit}>Transfer Tickets</PrimaryButton>
      </div>
    </div>
  );
}

function OtpScreen({ recipient, onBack, onCancel, onVerified }) {
  const [digits, setDigits] = useState(Array(6).fill(""));
  const [status, setStatus] = useState("idle");
  const [cooldown, setCooldown] = useState(0);
  const inputsRef = useRef([]);
  const lastAttempted = useRef("");

  const contactMasked =
    recipient.method === "email"
      ? recipient.email.replace(/^(.{2}).+(@.+)$/, "$1\u2022\u2022\u2022\u2022$2")
      : recipient.phone.replace(/.(?=.{4})/g, "\u2022");

  const sendCode = useCallback(() => {
    setStatus("sending");
    setTimeout(() => {
      setStatus("sent");
      setCooldown(30);
    }, 700);
  }, []);

  useEffect(() => {
    sendCode();
  }, [sendCode]);

  useEffect(() => {
    if (cooldown <= 0) return;
    const id = setTimeout(() => setCooldown((c) => c - 1), 1000);
    return () => clearTimeout(id);
  }, [cooldown]);

  const handleChange = (i, val) => {
    if (!/^[0-9]?$/.test(val)) return;
    const next = [...digits];
    next[i] = val;
    setDigits(next);
    if (val && i < 5) inputsRef.current[i + 1]?.focus();
  };

  const handlePaste = (e) => {
    const text = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, 6);
    if (!text) return;
    e.preventDefault();
    setDigits(text.padEnd(6, "").split("").slice(0, 6));
    inputsRef.current[Math.min(text.length, 5)]?.focus();
  };

  const code = digits.join("");

  const verify = useCallback(
    (candidate) => {
      const value = candidate ?? code;
      lastAttempted.current = value;
      setStatus("verifying");
      setTimeout(() => {
        if (value === DEMO_OTP) {
          onVerified();
        } else {
          setStatus("error");
        }
      }, 700);
    },
    [code, onVerified]
  );

  useEffect(() => {
    if (code.length === 6 && code !== lastAttempted.current && status !== "verifying" && status !== "sending") {
      verify(code);
    }
  }, [code, status, verify]);

  return (
    <div className="min-h-full flex flex-col bg-white">
      <TopBar title="Authentication" onCancel={onCancel} tone="blue" />
      <div className="p-4 flex flex-col items-center text-center">
        <div className="w-14 h-14 rounded-full bg-blue-50 flex items-center justify-center mb-4 mt-2">
          <Send size={22} className="text-blue-600" />
        </div>
        <div className="text-base font-bold text-gray-900">Authenticate Your Account</div>
        <div className="text-xs text-gray-500 mt-2" style={{ maxWidth: "280px" }}>
          A one-time code has been sent to {contactMasked}. Please enter your code below to continue.
        </div>

        {status === "sending" ? (
          <Spinner label="Sending code..." />
        ) : (
          <>
            <div className="text-xs font-medium text-gray-500 mt-6 mb-2 self-start">One-Time Code</div>
            <div className="flex gap-2" onPaste={handlePaste}>
              {digits.map((d, i) => (
                <input
                  key={i}
                  ref={(el) => (inputsRef.current[i] = el)}
                  value={d}
                  onChange={(e) => handleChange(i, e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Backspace" && !d && i > 0) inputsRef.current[i - 1]?.focus();
                  }}
                  inputMode="numeric"
                  maxLength={1}
                  className={
                    "w-10 h-12 text-center text-lg rounded border focus:outline-none focus:ring-1 focus:border-blue-600 focus:ring-blue-600 " +
                    (status === "error" ? "border-red-600" : "border-gray-300")
                  }
                />
              ))}
            </div>

            {status === "error" && (
              <div className="flex items-center gap-1 text-xs text-red-600 mt-3">
                <AlertCircle size={13} /> The verification code is incorrect. Please try again.
              </div>
            )}

            {status === "verifying" && (
              <div className="flex items-center gap-2 text-xs text-gray-500 mt-3">
                <Loader2 size={13} className="animate-spin text-blue-600" /> Verifying...
              </div>
            )}

            <div className="text-xs text-gray-500 mt-4">
              {cooldown > 0 ? (
                <>Resend code in {cooldown}s</>
              ) : (
                <button onClick={sendCode} className="text-blue-600 font-medium">
                  Resend code
                </button>
              )}
            </div>
          </>
        )}
      </div>

      <div className="mt-auto p-4 border-t border-gray-300">
        <PrimaryButton onClick={() => verify()} disabled={code.length !== 6} loading={status === "verifying"}>
          Confirm Code
        </PrimaryButton>
      </div>
    </div>
  );
}

function ProcessingScreen() {
  return (
    <div className="min-h-full flex flex-col bg-white">
      <TopBar title="Transfer Tickets" tone="blue" />
      <Spinner label="Processing transfer..." />
    </div>
  );
}

function SuccessScreen({ count, recipient, onDone }) {
  return (
    <div className="min-h-full flex flex-col bg-white px-6 py-10 items-center text-center">
      <div className="w-16 h-16 rounded-full bg-green-50 flex items-center justify-center mb-4">
        <Check size={28} className="text-green-600" />
      </div>
      <div className="text-lg font-bold text-gray-900">Transfer Complete</div>
      <div className="text-sm text-gray-500 mt-2" style={{ maxWidth: "280px" }}>
        {count} {count === 1 ? "ticket was" : "tickets were"} successfully transferred to {recipient.firstName} {recipient.lastName}.
      </div>
      <div className="text-xs text-gray-500 mt-4">
        {EVENT.titleLine2} &middot; {EVENT.dateLabel}
      </div>
      <PrimaryButton onClick={onDone} className="mt-8">
        Return to My Tickets
      </PrimaryButton>
    </div>
  );
}

function HistoryScreen({ transfers, onBack }) {
  return (
    <div className="min-h-full flex flex-col bg-white">
      <TopBar title="Transfer History" onBack={onBack} />
      {transfers.length === 0 ? (
        <div className="px-4 py-10 text-center text-sm text-gray-500">No transfers yet</div>
      ) : (
        <div className="p-4 flex flex-col gap-2">
          {transfers.map((tr) => (
            <div key={tr.id} className="border border-gray-300 rounded-md p-3">
              <div className="flex items-center justify-between">
                <div className="text-sm font-medium text-gray-900">{tr.recipientName}</div>
                <span className="text-xs font-medium px-1.5 py-0.5 rounded text-green-600 bg-green-50">Completed</span>
              </div>
              <div className="text-xs text-gray-500 mt-1">
                {tr.ticketCount} ticket{tr.ticketCount === 1 ? "" : "s"} &middot; {new Date(tr.date).toLocaleString()}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  App shell / state machine                                          */
/* ------------------------------------------------------------------ */

export default function App() {
  const [loaded, setLoaded] = useState(false);
  const [authed, setAuthed] = useState(false);
  const [pendingAuth, setPendingAuth] = useState(false);
  const [tickets, setTickets] = useState(INITIAL_TICKETS);
  const [transfers, setTransfers] = useState([]);
  const [view, setView] = useState("myTickets");
  const [selectedIds, setSelectedIds] = useState([]);
  const [recipient, setRecipient] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const value = await storageGet(STORAGE_KEY);
        if (value) {
          const parsed = JSON.parse(value);
          if (parsed.tickets) setTickets(parsed.tickets);
          if (parsed.transfers) setTransfers(parsed.transfers);
        }
      } catch (e) {
        // no saved state yet
      } finally {
        setLoaded(true);
      }
    })();
  }, []);

  useEffect(() => {
    if (!loaded) return;
    storageSet(STORAGE_KEY, JSON.stringify({ tickets, transfers }));
  }, [tickets, transfers, loaded]);

  const startTransfer = (ticketId) => {
    setSelectedIds(ticketId ? [ticketId] : []);
    setView("transferSelect");
  };

  const cancelTransfer = () => {
    setSelectedIds([]);
    setRecipient(null);
    setView("order");
  };

  const completeTransfer = (recipientInfo) => {
    setView("processing");
    setTimeout(() => {
      setTickets((prev) =>
        prev.map((t) =>
          selectedIds.includes(t.id)
            ? { ...t, status: "TRANSFERRED", recipientName: recipientInfo.firstName + " " + recipientInfo.lastName }
            : t
        )
      );
      setTransfers((prev) => [
        {
          id: "tr-" + Date.now(),
          recipientName: recipientInfo.firstName + " " + recipientInfo.lastName,
          ticketCount: selectedIds.length,
          date: new Date().toISOString(),
        },
        ...prev,
      ]);
      setView("success");
    }, 900);
  };

  if (!loaded) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 size={24} className="animate-spin text-blue-600" />
      </div>
    );
  }

  let screen = null;
  if (!authed) {
    screen = pendingAuth ? (
      <OtpScreen
        recipient={{ method: "email", email: DEMO_EMAIL }}
        onBack={() => setPendingAuth(false)}
        onCancel={() => setPendingAuth(false)}
        onVerified={() => {
          setPendingAuth(false);
          setAuthed(true);
          setView("myTickets");
        }}
      />
    ) : (
      <LoginScreen onLogin={() => setPendingAuth(true)} />
    );
  } else if (view === "myTickets") {
    screen = (
      <MyTicketsScreen
        tickets={tickets}
        onOpenOrder={() => setView("order")}
        onLogout={() => {
          setAuthed(false);
          setView("myTickets");
        }}
      />
    );
  } else if (view === "order") {
    screen = <OrderDetailScreen tickets={tickets} onBack={() => setView("myTickets")} onTransfer={startTransfer} onViewHistory={() => setView("history")} />;
  } else if (view === "transferSelect") {
    screen = (
      <TransferSelectScreen
        tickets={tickets}
        preselected={selectedIds[0]}
        onBack={() => setView("order")}
        onCancel={cancelTransfer}
        onContinue={(ids) => {
          setSelectedIds(ids);
          setView("transferMethod");
        }}
      />
    );
  } else if (view === "transferMethod") {
    screen = <TransferMethodScreen onBack={() => setView("transferSelect")} onCancel={cancelTransfer} onManual={() => setView("recipientForm")} />;
  } else if (view === "recipientForm") {
    screen = (
      <RecipientForm
        onBack={() => setView("transferMethod")}
        onCancel={cancelTransfer}
        onSubmit={(info) => {
          setRecipient(info);
          setView("otp");
        }}
      />
    );
  } else if (view === "otp") {
    screen = <OtpScreen recipient={recipient} onBack={() => setView("recipientForm")} onCancel={cancelTransfer} onVerified={() => completeTransfer(recipient)} />;
  } else if (view === "processing") {
    screen = <ProcessingScreen />;
  } else if (view === "success") {
    screen = (
      <SuccessScreen
        count={selectedIds.length}
        recipient={recipient}
        onDone={() => {
          setSelectedIds([]);
          setRecipient(null);
          setView("myTickets");
        }}
      />
    );
  } else if (view === "history") {
    screen = <HistoryScreen transfers={transfers} onBack={() => setView("order")} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex justify-center font-sans">
      <div className="w-full bg-white shadow-sm flex flex-col" style={{ maxWidth: "480px" }}>
        {screen}
      </div>
    </div>
  );
}
